function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

// A provider whose stream rejects with the given value itself, so the catch sees the raw shape a library would hand it.
